def find_exactly_one_pair(nums):
    from collections import Counter

    if len(nums) < 2:
        return False

    counts = Counter(nums)
    unique_elements = list(set(nums))

    # Check if there is exactly one pair of identical elements
    pair_count = 0
    for count in counts.values():
        if count >= 2:
            pair_count += 1
            # Break early if more than one pair exists
            if pair_count > 1:
                return False

    # If there is exactly one pair, return True, the value of the pair, and the unique elements
    if pair_count == 1:
        return (True, nums.count(min(nums)), unique_elements)
    else:
        return False
