def recursive_insertion_sort(arr, n=None):
    if n is None:
        n = len(arr)
    if n <= 1:
        return arr

    # Recursive case: sort the first n-1 elements
    sorted_rest = recursive_insertion_sort(arr[:n-1], n-1)

    # Insert the nth element into the sorted rest
    inserted = sorted_rest.insert(n-1, arr[n-1])
    return inserted

