def convert_to_base_8(number):
    if number == 0:
        return '0'

    # Work with absolute value to handle negatives
    sign = '-' if number < 0 else ''
    number = abs(number)

    # Convert to base 8
    digits = []
    while number > 0:
        digits.append(str(number % 8))
        number //= 8

    # Reverse the digits to get correct order
    digits = digits[::-1]

    # Reconstruct the result with sign
    if sign:
        return f"{sign}{''.join(digits)}"
    else:
        return ''.join(digits)
