def min_subarray_len_with_prime(s, nums):
    n = len(nums)
    if n == 0:
        return 0

    # Precompute prime status for numbers in range [-10000, 10000]
    min_val = -10000
    max_val = 10000
    is_prime = [True] * (max_val - min_val + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(max_val ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, max_val - min_val + 1, i):
                is_prime[j] = False

    # Map each number to its prime status
    prime_map = {num: is_prime[num - min_val] for num in nums}

    # Sliding window approach
    left = 0
    current_sum = 0
    min_len = float('inf')

    for right in range(n):
        current_sum += nums[right]
        right_val = nums[right]
        if prime_map[right_val]:
            # Found a prime in the current window
            min_len = min(min_len, right - left + 1)

        # Shrink window from left while sum >= s
        while current_sum >= s:
            left_val = nums[left]
            if prime_map[left_val]:
                min_len = min(min_len, right - left + 1)
            current_sum -= left_val
            left += 1

    return min_len if min_len != float('inf') else 0

