def convert_to_bytes(size_str):
    if not size_str:
        return size_str

    # Check for byte suffixes
    suffixes = {"Ki", "Mi", "Gi"}
    if any(size_str.endswith(s) for s in suffixes):
        value, unit = size_str.rsplit(None, 1)
        unit = unit.lower()

        # Map unit to bytes
        unit_map = {
            "k": 1024,
            "m": 1024 ** 2,
            "g": 1024 ** 3
        }

        if unit not in unit_map:
            return size_str  # Invalid unit, return unchanged

        try:
            value = int(value)
        except ValueError:
            return size_str  # Invalid numeric part, return unchanged

        return value * unit_map[unit]
    else:
        return size_str
