def fibonacci_memoization(n):
    """
    Computes the n-th Fibonacci number efficiently using memoization.
    The function is thread-safe without using any built-in synchronization mechanisms.

    Parameters:
        n (int): The index in the Fibonacci sequence (0 <= n <= 50).

    Returns:
        int: The n-th Fibonacci number.
    """
    # Use a dictionary to store computed values.
    # This dictionary is shared across threads but not synchronized.
    # Since the constraints limit n to 0 <= n <= 50, the dictionary size is small.
    memo = {}

    def fib_memoized(k):
        if k in memo:
            return memo[k]
        if k == 0:
            memo[k] = 0
        elif k == 1:
            memo[k] = 1
        else:
            memo[k] = fib_memoized(k - 1) + fib_memoized(k - 2)
        return memo[k]

    return fib_memoized(n)

