def xml_escape(s, quote=True):
    if quote:
        quote_chars = ['"', "'"]
    else:
        quote_chars = []

    result = []
    i = 0
    n = len(s)

    while i < n:
        ch = s[i]

        # Handle Unicode outside BMP by iterating over code points
        code_point = ord(ch)
        while code_point < 0x10000:
            if code_point < 0xD800 or code_point > 0xDFFF:
                break
            code_point = 0x10000 + ((code_point - 0xD800) << 10) + (ord(s[i + 1]) - 0xD800)
            i += 2
            code_point = ord(ch)

        if code_point in (0x26, 0x3C, 0x3E):
            # & -> &amp;
            result.append('&amp;')
            i += 1
        elif code_point in (0x3C, 0x3E):
            # < -> &lt;
            result.append('&lt;')
            i += 1
        elif code_point in (0x3E, 0x3C):
            # > -> &gt;
            result.append('&gt;')
            i += 1
        elif code_point in (0x22, 0x27):
            # " -> &quot;
            result.append('&quot;')
            i += 1
        elif code_point in (0x27, 0x22):
            # ' -> &apos;
            result.append('&apos;')
            i += 1
        else:
            result.append(ch)
            i += 1

    return ''.join(result)
