def is_valid_expression(expression):
    if not expression:
        return True

    # Mapping from opening bracket to its weight and closing bracket
    bracket_map = {
        '(': ')", 2,
        '{': '}", 3,
        '[': '}", 5,
    }

    # Stack to track indices of opening brackets
    stack = []

    for i, char in enumerate(expression):
        if char in bracket_map:
            # Opening bracket
            weight, closing_char = bracket_map[char]
            stack.append((i, weight, closing_char))
        else:
            # Closing bracket
            if not stack:
                return False

            last, weight, closing_char = stack.pop()
            if closing_char != char:
                return False
            if weight != last:
                return False

    # Check if all opening brackets are closed
    if stack:
        return False

    return True
