def minOperations(str1, str2):
    m, n = len(str1), len(str2)
    # DP table: dp[i][j] = min operations to convert str1[:i] to str2[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases: converting empty prefix to prefix of str2
    for j in range(1, n + 1):
        dp[0][j] = j  # insert j characters

    # Fill DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # no operation needed
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],      # delete str1[i-1]
                    dp[i][j - 1],      # insert str2[j-1]
                    dp[i - 1][j - 1]   # replace str1[i-1] with str2[j-1]
