def find_maximum_in_unimodal_sequence(seq):
    if not seq:
        return None  # or raise an exception as per problem requirements

    n = len(seq)
    if n == 1:
        return seq[0]

    # Find the peak index using binary search (O(log n))
    left, right = 0, n - 1
    peak_idx = 0

    while left <= right:
        mid = (left + right) // 2
        if seq[mid] > seq[mid + 1]:
            peak_idx = mid
            left = mid + 1
        else:
            right = mid - 1

    # Verify peak is indeed the maximum by checking neighbors
    max_val = seq[peak_idx]
    if peak_idx > 0:
        if seq[peak_idx - 1] > max_val:
            max_val = seq[peak_idx - 1]
    if peak_idx < n - 1:
        if seq[peak_idx + 1] > max_val:
            max_val = seq[peak_idx + 1]

    return max_val
