def find_largest_prime_factor(n: int) -> int:
    if n < 2:
        return 0

    # Handle factor 2 separately
    if n % 2 == 0:
        while n % 2 == 0:
            n //= 2
        if n == 1:
            return 2

    # Check odd factors from 3 upwards
    i = 3
    while i * i <= n:
        while n % i == 0:
            n //= i
        i += 2

    # If n is still greater than 1, then it's the largest prime factor
    if n > 1:
        return n

    return 1
