def convert_to_numeric(input_str):
    # Remove commas as thousands separators
    input_str = input_str.replace(',', '')

    # Find the first non-numeric character to determine the suffix position
    suffix_pos = -1
    for i, char in enumerate(input_str):
        if not char.isdigit() and not char in '.':
            suffix_pos = i
            break

    if suffix_pos == -1:
        # No suffix found
        try:
            return float(input_str)
        except ValueError:
            return None

    # Extract the numeric part before the suffix
    numeric_part = input_str[:suffix_pos]

    # Check if the suffix is valid
    suffix = input_str[suffix_pos + 1:].upper()
    if suffix not in ('K', 'M', 'B', 'T'):
        return None

    # Convert numeric_part to float
    num = float(numeric_part)

    # Apply the multiplier
    multiplier = {
        'K': 10**3,
        'M': 10**6,
        'B': 10**9,
        'T': 10**12
    }.get(suffix, 1)

    return num * multiplier
