def firstMissingPositive(nums):
    n = len(nums)
    # Use a boolean array to mark presence of numbers in the range [1, n]
    # Since the array can contain negative numbers and numbers outside [1, n],
    # we only care about numbers from 1 to n.
    present = [False] * (n + 1)

    for num in nums:
        if 1 <= num <= n:
            present[num] = True

    # Find the smallest index i (1-based) where present[i] is False
    for i in range(1, n + 1):
        if not present[i]:
            return i

    # If all numbers from 1 to n are present, the smallest missing is n + 1
    return n + 1

